+    private static String descriptionFileName(String description) {
+        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(description);
+        String keptWord = null;
+        while (matcher.find()) {
+            keptWord = matcher.group(1);
+        }
+        String hash = sha256(description);
+        String prefix = keptWord == null ? "rule" : keptWord;
+        String result = prefix + "-" + hash;
+        if (STORED_RULES_FILE_NAME.equals(result)) {
+            return "rule-" + hash;
+        }
+        return result;
+    }
