+        ensureFolder(folder);
+        indexExists = Files.exists(storedRulesFile, LinkOption.NOFOLLOW_LINKS);
+        if (indexExists && !Files.isRegularFile(storedRulesFile, LinkOption.NOFOLLOW_LINKS)) {
+            throw new StoreInitializationFailedException(String.format(
+                    "The violation store index %s is not a regular file directly in the store folder",
+                    storedRulesFile));
+        }
