+        Properties properties = indexExists ? loadProperties(storedRulesFile) : new Properties();
+        if (integrityMode == IntegrityMode.IGNORE) {
+            if (!indexExists) {
+                writeIndex(properties, storedRulesFile, folder);
+            }
+            state.properties = properties;
+            return;
+        }
+
+        IntegrityReport report = inspect(properties, folder, storedRulesFile);
+        if (integrityMode == IntegrityMode.FAIL && report.hasProblems()) {
+            throw new StoreInitializationFailedException(report.message(storedRulesFile));
+        }
+
+        boolean changed = false;
+        if (integrityMode == IntegrityMode.REPAIR) {
+            changed = repair(report, properties, folder, storedRulesFile);
+        }
+        if (!indexExists || changed) {
+            writeIndex(properties, storedRulesFile, folder);
+        }
+        state.properties = properties;
+    }
+
+    private void ensureFolder(Path folder) {
+        try {
+            if (Files.exists(folder, LinkOption.NOFOLLOW_LINKS)) {
+                if (!Files.isDirectory(folder, LinkOption.NOFOLLOW_LINKS)) {
+                    throw new StoreInitializationFailedException("Violation store path is not a directory: " + folder);
+                }
+            } else {
+                Files.createDirectories(folder);
+            }
+        } catch (StoreInitializationFailedException e) {
+            throw e;
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private Properties loadProperties(Path file) {
+        Properties result = new Properties();
+        try (FileInputStream inputStream = new FileInputStream(file.toFile())) {
+            result.load(inputStream);
+            return result;
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private StoreState getStoreState(Path folder) {
+        try {
+            String key = folder.toFile().getCanonicalPath();
+            return STORES_BY_PATH.computeIfAbsent(key, __ -> new StoreState());
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private Path folderPath() {
+        return storeFolder.toPath().toAbsolutePath().normalize();
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        StoreState state = requireInitialized();
+        state.lock.lock();
+        try {
+            return state.properties.containsKey(ensureUnixLineBreaks(rule.getDescription()));
+        } finally {
+            state.lock.unlock();
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        StoreState state = requireInitialized();
+        state.lock.lock();
+        try {
+            Path folder = folderPath();
+            Path index = folder.resolve(STORED_RULES_FILE_NAME);
+            String description = ensureUnixLineBreaks(rule.getDescription());
+            String existingName = state.properties.getProperty(description);
+
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
+                forgetRule(state, description, existingName, folder, index);
+                return;
+            }
+
+            String fileName = existingName == null ? createRuleFileName(rule.getDescription()) : existingName;
+            boolean newEntry = existingName == null;
+            Path writtenPath = writeRuleFile(fileName, violations, newEntry, folder, index);
+            if (newEntry) {
+                Properties updated = copyOf(state.properties);
+                updated.setProperty(description, ensureUnixLineBreaks(fileName));
+                try {
+                    writeIndex(updated, index, folder);
+                } catch (RuntimeException e) {
+                    deleteQuietly(writtenPath);
+                    throw e;
+                }
+                state.properties = updated;
+            }
+        } finally {
+            state.lock.unlock();
+        }
+    }
+
+    private String createRuleFileName(String description) {
+        String result = ruleViolationFileNameStrategy.createRuleFileName(description);
+        if (result == null || result.trim().isEmpty()) {
+            throw new StoreUpdateFailedException("The RuleViolationFileNameStrategy did not provide a file name");
+        }
+        return result;
+    }
+
+    private void forgetRule(StoreState state, String description, String fileName, Path folder, Path index) {
+        if (fileName == null) {
+            return;
+        }
+        Properties updated = copyOf(state.properties);
+        updated.remove(description);
+        if (isSharedFile(state.properties, description, fileName, folder)) {
+            writeIndex(updated, index, folder);
+            state.properties = updated;
+            return;
+        }
+
+        Path indexTemp = null;
+        try {
+            indexTemp = writeIndexToTemporaryFile(updated, index, folder);
+            deleteNamedFile(fileName, folder, index);
+            moveIntoPlace(indexTemp, index);
+            indexTemp = null;
+            state.properties = updated;
+        } catch (IOException e) {
+            deleteQuietly(indexTemp);
+            throw new StoreUpdateFailedException(e);
+        } catch (RuntimeException e) {
+            deleteQuietly(indexTemp);
+            throw e;
+        }
+    }
+
+    private boolean isSharedFile(Properties properties, String description, String fileName, Path folder) {
+        String normalizedName = ensureUnixLineBreaks(fileName);
+        Path file = resolveName(folder, fileName);
+        String identity = fileIdentity(file);
+        for (String otherDescription : properties.stringPropertyNames()) {
+            if (description.equals(otherDescription)) {
+                continue;
+            }
+            String otherName = properties.getProperty(otherDescription);
