+    private Path writeRuleFile(String fileName, List<String> violations, boolean newEntry, Path folder, Path index) {
+        Path file = writablePath(fileName, newEntry, folder, index);
+        Path destination = file;
+        try {
+            if (Files.exists(file, LinkOption.NOFOLLOW_LINKS) && Files.isSymbolicLink(file)) {
+                destination = realDirectPath(file, folder);
+            }
+            byte[] content = serializedViolations(violations);
+            Path temporary = Files.createTempFile(folder, ".violation-", ".tmp");
