+    private Path writablePath(String fileName, boolean newEntry, Path folder, Path index) {
+        Path path = resolveName(folder, fileName);
+        if (!isDirectPath(path, folder) || path.equals(index)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Refusing to write rule violations to unsafe file name '%s'", fileName));
+        }
+
+        boolean exists = Files.exists(path, LinkOption.NOFOLLOW_LINKS);
+        if (exists && newEntry) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Refusing to overwrite file '%s' that is not recorded by this rule", path));
+        }
+        if (exists) {
+            try {
+                if (Files.isSameFile(path, index)) {
+                    throw new StoreUpdateFailedException("Refusing to overwrite the stored.rules index");
+                }
+                if (!Files.isSymbolicLink(path) && !Files.isRegularFile(path, LinkOption.NOFOLLOW_LINKS)) {
+                    throw new StoreUpdateFailedException(String.format("Rule violation path is not a regular file: %s", path));
+                }
+                if (Files.isSymbolicLink(path)) {
+                    realDirectPath(path, folder);
+                }
+            } catch (IOException e) {
+                throw new StoreUpdateFailedException(e);
+            }
+        }
+        return path;
+    }
