+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        StoreState state = requireInitialized();
+        state.lock.lock();
+        try {
+            String fileName = state.properties.getProperty(ensureUnixLineBreaks(rule.getDescription()));
+            checkArgument(fileName != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(fileName);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        } finally {
+            state.lock.unlock();
+        }
+    }
+
+    private List<String> readLines(String ruleDetailsFileName) {
+        String violationsText = readStoreFile(ruleDetailsFileName);
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private String readStoreFile(String fileName) {
+        try {
+            return ensureUnixLineBreaks(new String(toByteArray(resolveName(folderPath(), fileName).toFile()), UTF_8));
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    private StoreState requireInitialized() {
+        if (storeState == null) {
+            throw new IllegalStateException("Violation store has not been initialized");
+        }
+        return storeState;
+    }
+
+    private IntegrityReport inspect(Properties properties, Path folder, Path index) {
+        List<EntryAnalysis> entries = new ArrayList<>();
+        List<String> descriptions = new ArrayList<>(properties.stringPropertyNames());
+        Collections.sort(descriptions);
+        for (String description : descriptions) {
+            String fileName = properties.getProperty(description);
+            FileInfo fileInfo = inspectFile(resolveName(folder, fileName), folder);
+            String derivedName = namingMode == NamingMode.RANDOM ? null : createIntegrityFileName(description);
+            entries.add(new EntryAnalysis(description, fileName, fileInfo, derivedName));
+        }
+
+        Map<String, List<EntryAnalysis>> entriesByName = groupByName(entries);
