+            if (entry.derivedName != null) {
+                entriesByDerivedName.computeIfAbsent(entry.derivedName, __ -> new ArrayList<>()).add(entry);
+            }
+        }
+
+        for (EntryAnalysis entry : entries) {
+            entry.shared = entriesByName.get(entry.fileName).size() > 1
+                    || (entry.fileInfo.identity != null && entriesByIdentity.get(entry.fileInfo.identity).size() > 1);
