/**
 * A text file based implementation of a {@link ViolationStore}.<br>
 * This {@link ViolationStore} stores the violations of every single {@link FreezingArchRule} in a dedicated file.
 * It keeps an index of all stored rules and a mapping to the individual rule violation files in the same folder.
 *
 * <p>The store can be configured through the following properties:</p>
 * <pre><code>
 * default.path=...               # string: the path of the folder where violation files will be stored
 * default.allowStoreCreation=... # boolean: whether to allow creating a new index file
 * default.allowStoreUpdate=...   # boolean: whether to allow updating any store file
 * default.fileNames=random       # random, description, or a RuleViolationFileNameStrategy class
 * default.integrity=ignore       # repair, fail, or ignore
 * </code></pre>
 */
@PublicAPI(usage = ACCESS)
public final class TextFileBasedViolationStore implements ViolationStore {
    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);

    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
    private static final Pattern DESCRIPTION_WORD_PATTERN = Pattern.compile("(?<![A-Za-z0-9])([A-Za-z0-9]{4,120})(?![A-Za-z0-9])");
    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
    private static final String STORE_PATH_DEFAULT = "archunit_store";
    private static final String STORED_RULES_FILE_NAME = "stored.rules";
    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
    private static final String FILE_NAMES_DEFAULT = "random";
    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
    private static final String INTEGRITY_DEFAULT = "ignore";

    private static final ConcurrentHashMap<String, StoreState> STORES_BY_PATH = new ConcurrentHashMap<>();

    private final RuleViolationFileNameStrategy constructorStrategy;
    private final boolean hasConstructorStrategy;

    private boolean storeCreationAllowed;
    private boolean storeUpdateAllowed;
    private IntegrityMode integrityMode;
    private NamingMode namingMode;
    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
    private File storeFolder;
    private StoreState storeState;

    /**
     * Creates a standard store that names newly stored rule violation files by random {@link UUID}s.
     *
     * @see #TextFileBasedViolationStore(RuleViolationFileNameStrategy)
     */
    public TextFileBasedViolationStore() {
        constructorStrategy = __ -> UUID.randomUUID().toString();
        hasConstructorStrategy = false;
    }

    /**
     * Creates a store with a custom strategy for rule violation file naming.
     *
     * @param ruleViolationFileNameStrategy controls how rule violation file names are derived
     */
    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
        checkArgument(ruleViolationFileNameStrategy != null, "Rule violation file name strategy must not be null");
        constructorStrategy = ruleViolationFileNameStrategy;
        hasConstructorStrategy = true;
    }

    @Override
    public void initialize(Properties properties) {
        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
        integrityMode = parseIntegrity(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));

        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Integrity repair requires %s.%s=true",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        if (hasConstructorStrategy && properties.containsKey(FILE_NAMES_PROPERTY_NAME)) {
            throw new StoreInitializationFailedException(String.format(
                    "Cannot configure %s when a RuleViolationFileNameStrategy was supplied to the constructor",
                    FILE_NAMES_PROPERTY_NAME));
        }
        configureFileNameStrategy(properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_DEFAULT));

        storeFolder = new File(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT));
        Path folder = folderPath();
        StoreState state = getStoreState(folder);
        state.lock.lock();
        try {
            log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), folder.resolve(STORED_RULES_FILE_NAME));
            initializeStore(state, folder);
            storeState = state;
        } finally {
            state.lock.unlock();
        }
    }

    private IntegrityMode parseIntegrity(String value) {
        if (IntegrityMode.REPAIR.value.equals(value)) {
            return IntegrityMode.REPAIR;
        }
        if (IntegrityMode.FAIL.value.equals(value)) {
            return IntegrityMode.FAIL;
        }
        if (IntegrityMode.IGNORE.value.equals(value)) {
            return IntegrityMode.IGNORE;
        }
        throw new StoreInitializationFailedException(String.format(
                "Invalid value for %s: '%s' (accepted values are repair, fail and ignore)",
                INTEGRITY_PROPERTY_NAME, value));
    }

    private void configureFileNameStrategy(String configuredValue) {
        if (hasConstructorStrategy) {
            namingMode = NamingMode.CUSTOM;
            ruleViolationFileNameStrategy = constructorStrategy;
            return;
        }
        if ("random".equals(configuredValue)) {
            namingMode = NamingMode.RANDOM;
            ruleViolationFileNameStrategy = constructorStrategy;
        } else if ("description".equals(configuredValue)) {
            namingMode = NamingMode.DESCRIPTION;
            ruleViolationFileNameStrategy = TextFileBasedViolationStore::descriptionFileName;
        } else {
            namingMode = NamingMode.CUSTOM;
            ruleViolationFileNameStrategy = loadFileNameStrategy(configuredValue);
        }
    }

    @SuppressWarnings("unchecked")
    private RuleViolationFileNameStrategy loadFileNameStrategy(String className) {
        try {
            Class<?> strategyClass = Class.forName(className);
            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyClass)) {
                throw new IllegalArgumentException("does not implement " + RuleViolationFileNameStrategy.class.getName());
            }
            Constructor<?> constructor = strategyClass.getConstructor();
            return (RuleViolationFileNameStrategy) constructor.newInstance();
        } catch (Exception e) {
            throw new StoreInitializationFailedException(String.format(
                    "Could not instantiate %s configured by %s='%s' (the class must be a public RuleViolationFileNameStrategy with a public no-argument constructor)",
                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, className), e);
        }
    }

    private static String descriptionFileName(String description) {
        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(description);
        String keptWord = null;
        while (matcher.find()) {
            keptWord = matcher.group(1);
        }
        String hash = sha256(description);
        String prefix = keptWord == null ? "rule" : keptWord;
        String result = prefix + "-" + hash;
        if (STORED_RULES_FILE_NAME.equals(result)) {
            return "rule-" + hash;
        }
