            appendEntries(result, "shared", entries.stream().filter(entry -> entry.shared).collect(toList()));
            appendEntries(result, "misplaced", entries.stream().filter(entry -> entry.misplaced).collect(toList()));
            appendEntries(result, "colliding", entries.stream().filter(entry -> entry.colliding).collect(toList()));
            appendEntries(result, "occupied", entries.stream().filter(entry -> entry.occupied).collect(toList()));
